ee:message.ee:set-payload:
%dw 2.0
import * from dw::util::Values
output application/json skipNullOn="everywhere"

fun markOption(orden: Array, idItem: String, idOrigen, idOpcion: String,descripcionEstadoOpcion: String, estadoOpcion:Boolean) = flatten(
    orden map 
        if ($.idItem == idItem and $.idOrigen == idOrigen) 
            $.productos.opciones map (o,i) ->  
                if (o.idOpcion == idOpcion ) 
                    if(o.estadoOpcion == null)
                        (o ++ (if( estadoOpcion == false)
                            { "estadoOpcion": {
                                "idItem": idItem,
                                "idOrigen": idOrigen,
                                "fecha ": now(),
                                "codigoEstado": "OPC11",
                                "nombreEstado": "ERROR-PROCESO_EN_SF",
                                "observaciones": descripcionEstadoOpcion}
                            } else { "estadoOpcion": {
                                "idItem": idItem,
                                "idOrigen": idOrigen,
                                "fecha ": now(),
                                "codigoEstado": "OPC20",
                                "nombreEstado": "RESPUESTA_SF_PROCESADA",
                                "observaciones": descripcionEstadoOpcion
                            }
                        })) else 
                            o update "estadoOpcion" with ((
                                if( estadoOpcion == false)
                                    {
                                        "idItem": idItem,
                                        "idOrigen": idOrigen,
                                        "fecha ": now(),
                                        "codigoEstado": "OPC11",
                                        "nombreEstado": "ERROR-PROCESO_EN_SF",
                                        "observaciones": descripcionEstadoOpcion
                                    } else { 
                                        "idItem": idItem,
                                        "idOrigen": idOrigen,
                                        "fecha ": now(),
                                        "codigoEstado": "OPC20",
                                        "nombreEstado": "RESPUESTA_SF_PROCESADA",
                                        "observaciones": descripcionEstadoOpcion
                                    }
                                ))
                else null
        else null
)

var sfResponseOptions  = vars.object_response.items map {
    "idItem": $.idItem,
    "idOrigen": $.idOrigen,
    "opciones": flatten($.productos map $.opciones ) ,
}

var opcionesWithId = flatten((sfResponseOptions map (o,i)-> {
                        "opciones": o.opciones map (op,ind)-> {
                            "idItem": o.idItem,
                            "idOrigen": o.idOrigen,
                            "idOpcion": op.idOpcion,
                            "estadoOpcion": op.estadoOpcion,
                            "descripcionEstadoOpcion": op.descripcionEstadoOpcion
                        }
                    }).opciones)
---
flatten(opcionesWithId map markOption(vars.order.items,$.idItem,$.idOrigen,$.idOpcion,$.descripcionEstadoOpcion,$.estadoOpcion))

%dw 2.0
import * from dw::util::Values
output application/json skipNullOn = "everywhere"
fun getOpcionInput(iOrigen, iItem, iOpcion, obj) = 
    ((obj filter $.estadoOpcion.idItem == iItem and $.estadoOpcion.idOrigen == iOrigen) filter $.idOpcion == iOpcion)[0]
var items = vars.order.items
var itemsOptionsUpdated = items map ((item, index) -> do{
    var products = if (sizeOf(payload filter $.estadoOpcion.idItem == item.idItem and $.estadoOpcion.idOrigen == item.idOrigen)!=0)
        item.productos update "opciones" with do{
            var options = item.productos.opciones map ((op, ind) -> do{
                var option = getOpcionInput(item.idOrigen, item.idItem, op.idOpcion, payload)
                ---
                if(option==null)
                    op
                else do{
                    var estado = option.estadoOpcion update "idOrigen" with null update "idItem" with null
                    ---
                    option update "estadoOpcion" with estado
                }

            })
            ---
            options
        }
        else item.productos
    ---
    item update "productos" with products
})
---
vars.order update "items" with itemsOptionsUpdated

%dw 2.0
import * from dw::util::Values
output application/json
fun actualizarEstadoItem(item) =
    if(item.productos.opciones.estadoOpcion.codigoEstado contains "OPC11")
        if(item.estadoItem == null)
            item ++ {
                "estadoItem": {
                    "fecha": now(),
                    "codigoEstado": "ITM61",
                    "nombreEstado": "ERROR-PROCESO_EN_SF",
                    "observaciones": "Contexto Integrador OM: " ++ "ITM61 " ++ ((item.productos.opciones.estadoOpcion filter $.codigoEstado ==  "OPC11").observaciones joinBy  " | ")
                }
            }
        else
            item update "estadoItem" with {
                "fecha": now(),
                "codigoEstado": "ITM61",
                "nombreEstado": "ERROR-PROCESO_EN_SF",
                "observaciones": "Contexto Integrador OM: " ++ "ITM61 " ++ ((item.productos.opciones.estadoOpcion filter $.codigoEstado == "OPC11").observaciones joinBy  " | ")
            }
    else
        if(item.estadoItem == null)
            item ++ {
                "estadoItem": {
                    "fecha": now(),
                    "codigoEstado": "ITM70",
                    "nombreEstado": "RESPUESTA_SF_PROCESADA",
                    "observaciones": "RESPUESTA_SF_PROCESADA"
                }
            }
        else
            item update "estadoItem" with {
                "fecha": now(),
                "codigoEstado": "ITM70",
                "nombreEstado": "RESPUESTA_SF_PROCESADA",
                "observaciones": "RESPUESTA_SF_PROCESADA"
            }
fun actualizarItems(items) = items map ((item, index) -> 
    if(vars.object_response.items.idItem contains item.idItem)
        actualizarEstadoItem(item)
    else 
        item
)
---
payload update "items" with actualizarItems(payload.items)

set-variable.value:
#[vars.object_response.items filter ((item, index) -> 
    item.idRaiz == null or item.idRaiz == '' or item.idRaiz == item.idItem
)]

#[vars.object_response.items filter ((item, index) -> 
    item.idRaiz != null and item.idRaiz != '' and item.idRaiz != item.idItem
)]

ee:variables.ee:set-variable:
%dw 2.0
output application/xml writeDeclaration=false
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tem http://tempuri.org/
ns tier http://schemas.datacontract.org/2004/07/Tier.Common
ns ws http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts
fun asignarHijos(idItem, hijos) = (
    (hijos filter idItem == $.idRaiz) map ((item, index) -> 
        {
            ws#"ProductoRespuesta": {
                ws#"DescripcionEstadoProducto": item.descripcionEstadoItem,
                ws#"EstadoProducto": item.estadoItem,
                ws#"IdItem": item.idItem,
                ws#"IdProducto": null,
                ws#"IdRaiz": item.idRaiz,
                ws#"Opciones": [
                    ws#"Opcion": getOpciones(item)
                ],
                ws#"SubProductos": do{
                    var asigHijos = asignarHijos(item.idItem, vars.hijos).ProductoRespuesta
                    ---
                    if(asigHijos != null) {ws#"ProductoRespuesta": asigHijos}
                    else null
                }
            }
        }
    )
)
fun getOpciones(item) = flatten(item.productos.opciones)
---
soapenv#"Envelope" @(
    "xmlns:tem": "http://tempuri.org/",
"xmlns:tier" : "http://schemas.datacontract.org/2004/07/Tier.Common",
    "xmlns:ws" : "http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts"
): {
    soapenv#"Header": null,
    soapenv#"Body": {
        tem#"RespuestaTransaccion": {
            tem#"WSRequestHeader": {
                tier#"property": {
                    tier#"Scheme_Services.Property": {
                        tier#"name": null,
                        tier#"value": null
                    }
                },
                tier#"system": {
                    tier#"correlationId": vars.rootMessage.typedValue.correlationId,
                    tier#"name": null,
                    tier#"processingServer": null
                }
            },
            tem#"WSRequestBody": {
                ws#"Descripcion": null,
                ws#"Fecha": vars.rootMessage.typedValue.fechaSolicitud,
                ws#"IdServicio": null,
                ws#"NumeroSolicitud": payload.idOrigen,
                ws#"OrdenOM": vars.rootMessage.typedValue.ordenOM,
                ws#"Productos": {
                    ws#"ProductoRespuesta": {
                        ws#"DescripcionEstadoProducto": payload.descripcionEstadoItem,
                        ws#"EstadoProducto": payload.estadoItem,
                        ws#"IdItem": payload.idItem,
                        ws#"IdProducto": null,
                        ws#"IdRaiz": payload.idRaiz,
                        ws#"Opciones": [
                            ws#"Opcion": getOpciones(payload)
                        ],
                        ws#"SubProductos": do{
                            var asigHijos = asignarHijos(payload.idItem, vars.hijos).ProductoRespuesta
                            ---
                            if(asigHijos != null) {ws#"ProductoRespuesta": asigHijos}
                            else null
                        }                    
                    }
                },
                ws#"Resultado": p('gestor.resultado'),
                ws#"TipoSolicitud": vars.rootMessage.typedValue.tipoSolicitud,
                ws#"TipoTransaccion": if ( upper(vars.rootMessage.typedValue.tipoSolicitud) == "APROVISIONAMIENTO") "Confirmar" else "Cerrar"
            }
        }
    }
}

%dw 2.0
output application/json
fun deconstruct(data, parent) = 
data map ((item, index) ->
    if (!isEmpty(item.SubProductos.*ProductoRespuesta))
    ([ item : {
            "idItem": item.IdItem
        } ] ++ deconstruct(item.SubProductos.*ProductoRespuesta, item.idItem))
else { item : {
        "idItem": item.IdItem
    } })
---
deconstruct(vars.bodyRespuestaTransaccion.Envelope.Body.RespuestaTransaccion.WSRequestBody.Productos.*ProductoRespuesta, vars.bodyRespuestaTransaccion.Envelope.Body.RespuestaTransaccion.WSRequestBody.Productos)..item.idItem
